// C116 (ER-40): every generated or pinned file is covered by an entry of the generator registry `docs/generators.toml`.
// A file is taken as generated when its first lines say so ("@generated", "Generated by/from ...", "automatically generated",
// "do not edit") or when it sits at a path that is generated by name (THIRD_PARTY_NOTICES.md, messages*.xlf, *.generated.*, a
// `generated/` folder of TypeScript, lockfiles, Tauri's permissions/autogenerated). Each such file must match the `outputs` of an
// entry, so a new generated file cannot exist without a check (`./dev gen check`, `./dev merge check`) and a regenerate command.
// Also: an `outputs` glob that matches no tracked file is a warning (the registry names something that is gone).
// Not covered on purpose (EXEMPT): folders whose lockfiles and copies are no product, no gate reads and a person never edits:
// fuzz targets, spikes, vendored sources, test fixtures, research harnesses.
// Positive control (ER-33): the registry is read and has entries, else the check is broken, not clean. Only a repository that
// has `docs/generators.toml` is checked (the Paddock repository); any other root reports nothing.
import { execFileSync } from 'node:child_process';
import { closeSync, openSync, readSync } from 'node:fs';
import { join } from 'node:path';
import { error, unwaivable, warn } from '../finding.mjs';

export const REGISTRY = 'docs/generators.toml';

/** Paths no registry entry has to cover (see the header). */
export const EXEMPT = [
  /(^|\/)fuzz\//,
  /^spikes\//,
  /(^|\/)vendor\//,
  /(^|\/)tests?\/(fixtures|golden)\//,
  /^conformance\/fixtures\//,
  /\/harness\//,
  /^docs\/research\//,
  /(^|\/)node_modules\//,
];

const NAMED = [
  /(^|\/)THIRD_PARTY_NOTICES\.md$/,
  /(^|\/)messages[^/]*\.xlf$/,
  /\.generated\.[a-z]+$/,
  /\/generated\/[^/]+\.ts$/,
  /(^|\/)Cargo\.lock$/,
  /(^|\/)package-lock\.json$/,
  /(^|\/)permissions\/autogenerated\//,
];

// A comment line (`//`, `#`, `;`, `/*`, `<!--`; not a `//!` or `///` doc comment, which describes code) that says the file is
// generated: "@generated", "[This file is] [automatically] generated by/from/with ...", "auto-generated", "do not edit".
const HEADER = /^\s*(?:\/\/(?![!/])|#|;|\/\*+|<!--|\*)\s*(?:.*@generated|(?:this file is |file is )?(?:automatically |auto-?)?generated (?:by|from|with)\b|.*\bdo not edit\b)/im;
const TEXT = /\.(ts|rs|toml|json|nsh|lock|mjs|js|scss|css|html|yml|yaml|sh|py|xlf|svg|service|plist)$/;

/** A glob over slash paths: `*` and `?` stay in a folder, `**` crosses folders (`**\/x` also matches `x`). */
export function globRegex(glob) {
  let re = '^';
  for (let i = 0; i < glob.length; i++) {
    const c = glob[i];
    if (c === '*' && glob[i + 1] === '*') {
      if (glob[i + 2] === '/') {
        re += '(?:.*/)?';
        i += 2;
      } else {
        re += '.*';
        i += 1;
      }
    } else if (c === '*') re += '[^/]*';
    else if (c === '?') re += '[^/]';
    else re += c.replace(/[.+^${}()|[\]\\]/g, '\\$&');
  }
  return new RegExp(`${re}$`);
}

/** The entries of the registry text: [{ id, outputs: [glob] }]. Reads the one-line or multi-line `outputs = [...]` of each [[generator]]. */
export function parseRegistry(text) {
  return text
    .split(/^\[\[generator\]\]\s*$/m)
    .slice(1)
    .map((body) => {
      const id = /^id\s*=\s*"([^"]+)"/m.exec(body)?.[1] ?? '?';
      const list = /^outputs\s*=\s*\[([^\]]*)\]/m.exec(body)?.[1] ?? '';
      const outputs = [...list.replace(/#.*$/gm, '').matchAll(/"((?:[^"\\]|\\.)*)"/g)].map((m) => m[1]);
      return { id, outputs };
    });
}

/** Whether the first lines of `head` say the file is generated. */
export function saysGenerated(head) {
  return HEADER.test(head.split('\n').slice(0, 5).join('\n'));
}

function head(root, file) {
  let fd;
  try {
    fd = openSync(join(root, file), 'r');
    const buf = Buffer.alloc(600);
    const n = readSync(fd, buf, 0, 600, 0);
    return buf.subarray(0, n).toString('utf8');
  } catch {
    return '';
  } finally {
    if (fd !== undefined) closeSync(fd);
  }
}

export default {
  id: 'C116',
  scope: 'root',
  mode: 'gate',
  title: 'Every generated or pinned file is covered by the generator registry',
  rule: 40,
  run(ctx) {
    const text = ctx.read(REGISTRY);
    if (text === null || text === undefined) return []; // not a repository with a registry
    const entries = parseRegistry(text);
    if (entries.length === 0) {
      return [unwaivable(error('C116', 40, REGISTRY, 1, `${REGISTRY} names no [[generator]] entry: the check cannot tell what is covered`, 'Add the entries (id, check, regenerate, paths, outputs, cost).'), 'check-broken')];
    }
    const git = ctx.options.git ?? ((args) => execFileSync('git', args, { cwd: ctx.root, encoding: 'utf8', maxBuffer: 256 << 20 }));
    let files;
    try {
      files = git(['ls-files', '-z', '--', '.']).split('\0').filter(Boolean);
    } catch {
      files = ctx.files(); // not a git checkout: every file under the root
    }
    const compiled = entries.map((e) => ({ ...e, res: e.outputs.map(globRegex) }));
    const covered = (f) => compiled.some((e) => e.res.some((r) => r.test(f)));
    const out = [];
    for (const f of files) {
      if (EXEMPT.some((r) => r.test(f))) continue;
      const byName = NAMED.some((r) => r.test(f));
      const byHeader = !byName && TEXT.test(f) && saysGenerated(head(ctx.root, f));
      if ((byName || byHeader) && !covered(f)) {
        out.push(
          error('C116', 40, f, 1, `${f} is ${byName ? 'generated by name' : 'marked generated in its first lines'} but no entry of ${REGISTRY} lists it in \`outputs\``, `Add the generator that writes it to ${REGISTRY} (id, check, regenerate, paths, outputs), or add its path to the \`outputs\` of the entry that does. A generated file is regenerated, never edited (ER-40).`),
        );
      }
    }
    const tracked = new Set(files);
    for (const e of compiled) {
      for (let i = 0; i < e.outputs.length; i++) {
        if (![...tracked].some((f) => e.res[i].test(f))) {
          out.push(warn('C116', 40, REGISTRY, 1, `entry \`${e.id}\`: the outputs glob \`${e.outputs[i]}\` matches no tracked file`, 'Remove the glob, or fix it to the files the generator writes.'));
        }
      }
    }
    return out;
  },
};
